from collections import defaultdict
from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Maps employee name -> dict of year -> used leave days
        self._used_days: dict[str, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def _is_leave_day(self, current: date) -> bool:
        # Monday is 0, Sunday is 6; weekends are 5 and 6
        if current.weekday() >= 5:
            return False
        if current in self.holidays:
            return False
        return True

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        # Count requested leave days partitioned by year
        days_by_year: dict[int, int] = defaultdict(int)
        current = start
        one_day = timedelta(days=1)
        while current <= end:
            if self._is_leave_day(current):
                days_by_year[current.year] += 1
            current += one_day

        # Check if the employee has enough remaining leave in each affected year
        for year, needed in days_by_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient leave days remaining for employee '{employee}' in year {year}."
                )

        # Deduct leave days
        total_used = 0
        for year, needed in days_by_year.items():
            self._used_days[employee][year] += needed
            total_used += needed

        return total_used

    def remaining(self, employee: str, year: int) -> int:
        """Returns the number of remaining leave days for an employee in a given year."""
        used = self._used_days[employee][year]
        return self.days_per_year - used
```

